    with SingleTickerProviderStateMixin {
  late Future<List<Object>> _dashboardFuture;

  late final AnimationController _fadeController;

  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage page) {
        return page.items;
      }),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<Object> results) {
      _currencies = results[0] as List<CurrencyModel>;
      _news = results[1] as List<NewsModel>;

      _fadeController.forward();

      currencyRepository.saveCurrencyList(_currencies);
      newsRepository.saveNewsList(_news);

      return results;
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<List<Object>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<List<Object>> snapshot) {
          if (snapshot.hasError) {
            return Center(child: Text('Ошибка: ${snapshot.error}'));
          }

          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel> currencies = _currencies;
          final List<NewsModel> news = _news;

          return FadeTransition(
            opacity: _fadeController.view,
            child: ListView(
              padding: const EdgeInsets.all(16),
              children: [
                // Currency section
                Text(
                  'Курс валют',
                  style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 8),
                if (currencies.isEmpty)
                  const Text('Нет данных')
                else
                  Column(
                    children: currencies.take(5).map((CurrencyModel currency) {
                      return Padding(
                        padding: const EdgeInsets.symmetric(vertical: 4),
                        child: Text(
                          '${currency.name}: ${currency.value.toStringAsFixed(4)}',
                          style: const TextStyle(fontSize: 16),
                        ),
                      );
                    }).toList(),
                  ),
                const SizedBox(height: 24),

